{
  "name": "Lumina Studio AI - High-End Product Photography",
  "description": "Professional background replacement tool for product photography, transforming simple snapshots into luxury lifestyle images while preserving the original product integrity.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum SceneStyle {
  MODERN_LUXURY = 'Modern Luxury',
  NORDIC_MINIMALIST = 'Nordic Minimalist',
  INDUSTRIAL_CHIC = 'Industrial Chic',
  CLASSIC_ELEGANCE = 'Classic Elegance',
  RUSTIC_WARMTH = 'Rustic Warmth',
  FUTURISTIC_TECH = 'Futuristic Tech'
}

export enum ImageSize {
  SIZE_1K = '1K',
  SIZE_2K = '2K',
  SIZE_4K = '4K'
}

export interface GenerationConfig {
  style: SceneStyle;
  customPrompt: string;
  isPro: boolean;
  size: ImageSize;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export interface GenerationResult {
  originalUrl: string;
  resultUrl: string;
  id: string;
}

import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { SceneStyle, ImageSize } from "./types";

const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const replaceBackground = async (
  base64Image: string,
  style: SceneStyle,
  customPrompt: string,
  isPro: boolean = false,
  size: ImageSize = ImageSize.SIZE_1K
): Promise<string> => {
  const ai = getAIClient();
  const modelName = isPro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const stylePrompts: Record<SceneStyle, string> = {
    [SceneStyle.MODERN_LUXURY]: "Place the product in a high-end luxury penthouse with floor-to-ceiling windows, marble floors, and sophisticated lighting.",
    [SceneStyle.NORDIC_MINIMALIST]: "Place the product in a bright, airy Scandinavian room with light wood furniture, soft textiles, and clean lines.",
    [SceneStyle.INDUSTRIAL_CHIC]: "Place the product in a loft with exposed brick walls, concrete floors, and large industrial windows with sunset light.",
    [SceneStyle.CLASSIC_ELEGANCE]: "Place the product in a grand heritage mansion room with ornate moldings, mahogany furniture, and velvet accents.",
    [SceneStyle.RUSTIC_WARMTH]: "Place the product in a cozy cabin or stone house with natural textures, warm golden hour lighting, and organic surroundings.",
    [SceneStyle.FUTURISTIC_TECH]: "Place the product in a sleek, neo-futuristic laboratory or modern office with neon accents and high-tech surfaces."
  };

  const finalPrompt = `
    TASK: BACKGROUND REPLACEMENT.
    STRICT RULE: KEEP THE MAIN PRODUCT EXACTLY AS IT IS. Do not change its shape, color, texture, or gloss.
    INSTRUCTION: ${stylePrompts[style]} ${customPrompt ? `Additional user request: ${customPrompt}` : ''}
    LIGHTING: Ensure the product's lighting and shadows perfectly match the new environment. 
    REALISM: Add realistic reflections of the new background on the product surface if it's shiny.
    OUTPUT: A professional, high-resolution lifestyle photograph.
  `;

  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image.split(',')[1],
    },
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [imagePart, { text: finalPrompt }] },
    config: isPro ? {
      imageConfig: {
        aspectRatio: "1:1",
        imageSize: size
      }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("No image data returned from Gemini");
};

export const startChat = async (history: {role: 'user' | 'model', parts: {text: string}[]}[]) => {
  const ai = getAIClient();
  const chat = ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: "You are a professional photography assistant at Lumina Studio. You help users with product photography tips, lighting advice, and creative scene ideas. Be helpful, concise, and professional."
    }
  });
  return chat;
};

import React, { useState, useCallback, useRef } from 'react';
import { 
  Camera, 
  Upload, 
  Sparkles, 
  Download, 
  MessageSquare, 
  X, 
  ChevronRight,
  Settings,
  RefreshCw,
  Zap,
  Check
} from 'lucide-react';
import { SceneStyle, ImageSize, GenerationConfig, ChatMessage, GenerationResult } from './types';
import { replaceBackground, startChat } from './geminiService';
import { GoogleGenAI } from '@google/genai';

const App: React.FC = () => {
  const [selectedFile, setSelectedFile] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [config, setConfig] = useState<GenerationConfig>({
    style: SceneStyle.MODERN_LUXURY,
    customPrompt: '',
    isPro: false,
    size: ImageSize.SIZE_1K
  });

  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatting, setIsChatting] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setSelectedFile(event.target?.result as string);
        setResult(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!selectedFile) return;

    setIsProcessing(true);
    try {
      if (config.isPro) {
        // @ts-ignore
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) {
          // @ts-ignore
          await window.aistudio.openSelectKey();
        }
      }

      const resultUrl = await replaceBackground(
        selectedFile,
        config.style,
        config.customPrompt,
        config.isPro,
        config.size
      );

      setResult({
        originalUrl: selectedFile,
        resultUrl,
        id: Date.now().toString()
      });
    } catch (error: any) {
      console.error("Generation failed:", error);
      if (error.message?.includes("Requested entity was not found")) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      } else {
        alert("Failed to generate image. Please try again.");
      }
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;

    const userMsg: ChatMessage = { role: 'user', text: chatInput };
    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatting(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const chat = ai.chats.create({
        model: 'gemini-3-pro-preview',
      });
      const response = await chat.sendMessage({ message: chatInput });
      const modelMsg: ChatMessage = { role: 'model', text: response.text || 'Sorry, I could not process that.' };
      setChatMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      console.error("Chat error:", error);
    } finally {
      setIsChatting(false);
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const downloadImage = () => {
    if (!result) return;
    const link = document.createElement('a');
    link.href = result.resultUrl;
    link.download = `lumina-studio-${result.id}.png`;
    link.click();
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#0a0a0a] text-white">
      {/* Sidebar Controls */}
      <aside className="w-full md:w-80 border-r border-white/10 bg-[#0f0f0f] p-6 flex flex-col gap-8 overflow-y-auto">
        <header className="flex items-center gap-3">
          <div className="p-2 bg-indigo-600 rounded-lg">
            <Sparkles className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="font-bold text-lg leading-tight">Lumina Studio</h1>
            <p className="text-xs text-white/40 uppercase tracking-widest font-medium">AI Photography</p>
          </div>
        </header>

        <div className="space-y-6">
          {/* Upload Area */}
          <div className="space-y-3">
            <label className="text-sm font-semibold text-white/60 block">1. Product Image</label>
            <div className={`relative group cursor-pointer border-2 border-dashed ${selectedFile ? 'border-indigo-500/50' : 'border-white/10'} rounded-xl transition-all hover:border-indigo-500/50 aspect-square overflow-hidden flex flex-col items-center justify-center bg-white/5`}>
              {selectedFile ? (
                <img src={selectedFile} alt="Uploaded" className="w-full h-full object-contain p-2" />
              ) : (
                <div className="text-center p-4">
                  <Upload className="w-8 h-8 text-white/20 mx-auto mb-2" />
                  <p className="text-xs text-white/40">Drop your product photo here or click to browse</p>
                </div>
              )}
              <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" />
            </div>
          </div>

          {/* Style Selector */}
          <div className="space-y-3">
            <label className="text-sm font-semibold text-white/60 block">2. Select Scene Style</label>
            <select 
              value={config.style}
              onChange={(e) => setConfig({...config, style: e.target.value as SceneStyle})}
              className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 appearance-none cursor-pointer"
            >
              {Object.values(SceneStyle).map(style => (
                <option key={style} value={style} className="bg-[#0f0f0f]">{style}</option>
              ))}
            </select>
          </div>

          {/* DIY Context */}
          <div className="space-y-3">
            <div className="flex justify-between items-center">
              <label className="text-sm font-semibold text-white/60 block">3. Custom DIY Context</label>
              <span className="text-[10px] text-white/30 uppercase tracking-tighter">Optional</span>
            </div>
            <textarea 
              placeholder="e.g. Add some scattered rose petals or a coffee cup next to it..."
              value={config.customPrompt}
              onChange={(e) => setConfig({...config, customPrompt: e.target.value})}
              className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-sm h-24 focus:outline-none focus:ring-2 focus:ring-indigo-500 resize-none"
            />
          </div>

          {/* Pro Settings Toggle */}
          <div className="pt-4 border-t border-white/10 space-y-4">
             <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                   <Zap className={`w-4 h-4 ${config.isPro ? 'text-amber-400' : 'text-white/20'}`} />
                   <span className="text-sm font-medium">Pro Generation</span>
                </div>
                <button 
                  onClick={() => setConfig({...config, isPro: !config.isPro})}
                  className={`w-10 h-5 rounded-full relative transition-colors ${config.isPro ? 'bg-amber-500' : 'bg-white/10'}`}
                >
                  <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${config.isPro ? 'left-6' : 'left-1'}`} />
                </button>
             </div>

             {config.isPro && (
               <div className="space-y-3 animate-in fade-in slide-in-from-top-2">
                 <label className="text-xs font-semibold text-white/40 uppercase">Output Resolution</label>
                 <div className="grid grid-cols-3 gap-2">
                    {Object.values(ImageSize).map(size => (
                      <button
                        key={size}
                        onClick={() => setConfig({...config, size})}
                        className={`py-2 text-xs rounded-lg border transition-all ${config.size === size ? 'bg-white/10 border-white/40' : 'border-white/5 text-white/40 hover:bg-white/5'}`}
                      >
                        {size}
                      </button>
                    ))}
                 </div>
                 <p className="text-[10px] text-white/30 leading-relaxed">
                   * Pro mode requires a billing-enabled Google AI Studio API key.
                 </p>
               </div>
             )}
          </div>
        </div>

        {/* Generate Button */}
        <button 
          onClick={handleGenerate}
          disabled={!selectedFile || isProcessing}
          className={`w-full py-4 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${isProcessing ? 'bg-white/5 text-white/20 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-500 active:scale-95 shadow-lg shadow-indigo-900/20'}`}
        >
          {isProcessing ? (
            <>
              <RefreshCw className="w-5 h-5 animate-spin" />
              Processing...
            </>
          ) : (
            <>
              <Sparkles className="w-5 h-5" />
              Generate Scene
            </>
          )}
        </button>
      </aside>

      {/* Main Viewport */}
      <main className="flex-1 p-6 md:p-12 flex flex-col items-center justify-center relative overflow-hidden bg-gradient-to-br from-[#0a0a0a] to-[#121212]">
        <div className="max-w-4xl w-full h-full flex flex-col items-center justify-center gap-8">
          {!result && !isProcessing && (
            <div className="text-center space-y-6 opacity-40">
              <div className="relative inline-block">
                <Camera className="w-24 h-24 mx-auto text-indigo-500" />
                <Sparkles className="w-8 h-8 absolute -top-2 -right-2 text-white animate-pulse" />
              </div>
              <div className="space-y-2">
                <h2 className="text-2xl font-light tracking-tight">Ready to transform your photo</h2>
                <p className="text-sm max-w-sm mx-auto">Upload a simple product photo on the left and watch it become a premium lifestyle shot.</p>
              </div>
            </div>
          )}

          {isProcessing && (
            <div className="space-y-8 text-center animate-in fade-in zoom-in duration-500">
               <div className="relative w-80 h-80 mx-auto">
                 <div className="absolute inset-0 rounded-full border-2 border-indigo-500/20 animate-ping" />
                 <div className="absolute inset-4 rounded-full border-2 border-indigo-500/40 animate-[ping_2s_infinite]" />
                 <div className="absolute inset-0 flex items-center justify-center">
                    <img src={selectedFile!} className="w-48 h-48 object-contain rounded-2xl opacity-50 grayscale" />
                    <div className="absolute inset-0 bg-gradient-to-t from-[#0a0a0a] via-transparent to-transparent" />
                 </div>
               </div>
               <div className="space-y-3">
                  <h3 className="text-xl font-medium">Reimagining your background...</h3>
                  <div className="flex items-center justify-center gap-2 text-white/40 text-sm">
                    <span className="flex h-1.5 w-1.5 rounded-full bg-indigo-500 animate-bounce" style={{animationDelay: '0ms'}} />
                    <span className="flex h-1.5 w-1.5 rounded-full bg-indigo-500 animate-bounce" style={{animationDelay: '150ms'}} />
                    <span className="flex h-1.5 w-1.5 rounded-full bg-indigo-500 animate-bounce" style={{animationDelay: '300ms'}} />
                    Analysing lighting & perspective
                  </div>
               </div>
            </div>
          )}

          {result && !isProcessing && (
            <div className="w-full space-y-6 animate-in fade-in slide-in-from-bottom-8 duration-700">
              <div className="relative rounded-2xl overflow-hidden shadow-2xl shadow-black/50 aspect-square md:aspect-video group">
                 <img src={result.resultUrl} alt="Generated result" className="w-full h-full object-cover" />

                 {/* Floating comparison/tools */}
                 <div className="absolute bottom-6 left-6 right-6 flex justify-between items-center opacity-0 group-hover:opacity-100 transition-opacity">
                    <div className="bg-black/80 backdrop-blur-md px-4 py-2 rounded-full border border-white/10 flex items-center gap-3">
                       <div className="flex items-center gap-2">
                         <div className="w-2 h-2 rounded-full bg-green-500" />
                         <span className="text-[10px] uppercase font-bold tracking-widest text-white/60">Product Intact</span>
                       </div>
                       <div className="w-px h-3 bg-white/20" />
                       <div className="flex items-center gap-2">
                         <div className="w-2 h-2 rounded-full bg-indigo-500" />
                         <span className="text-[10px] uppercase font-bold tracking-widest text-white/60">Scene Replaced</span>
                       </div>
                    </div>

                    <button 
                      onClick={downloadImage}
                      className="p-4 bg-white text-black rounded-full shadow-xl hover:scale-105 transition-transform"
                    >
                      <Download className="w-6 h-6" />
                    </button>
                 </div>
              </div>

              <div className="flex items-center justify-center gap-4">
                 <button 
                   onClick={() => setResult(null)}
                   className="px-6 py-2.5 rounded-full border border-white/10 text-sm font-medium hover:bg-white/5 transition-colors flex items-center gap-2"
                 >
                   <RefreshCw className="w-4 h-4" />
                   Start New
                 </button>
              </div>
            </div>
          )}
        </div>

        {/* Branding Watermark */}
        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 text-white/10 text-xs font-bold tracking-[0.3em] pointer-events-none uppercase">
          Precision Studio Engine
        </div>
      </main>

      {/* Floating Assistant Button */}
      <button 
        onClick={() => setShowChat(!showChat)}
        className={`fixed bottom-8 right-8 p-4 rounded-full shadow-2xl transition-all duration-300 z-50 ${showChat ? 'bg-red-500 rotate-90' : 'bg-indigo-600 hover:scale-110 active:scale-95'}`}
      >
        {showChat ? <X className="w-6 h-6" /> : <MessageSquare className="w-6 h-6" />}
      </button>

      {/* Chat Window */}
      {showChat && (
        <div className="fixed bottom-24 right-8 w-80 md:w-96 h-[500px] bg-[#121212] border border-white/10 rounded-2xl shadow-2xl flex flex-col z-50 animate-in slide-in-from-bottom-10 fade-in duration-300 overflow-hidden">
          <header className="p-4 border-b border-white/10 bg-white/5 flex items-center gap-3">
            <div className="p-1.5 bg-indigo-500 rounded-lg">
              <Sparkles className="w-4 h-4" />
            </div>
            <div>
              <h4 className="text-sm font-bold">Lumina Assistant</h4>
              <p className="text-[10px] text-green-500 flex items-center gap-1">
                <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
                Gemini 3 Pro Active
              </p>
            </div>
          </header>

          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            {chatMessages.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-center space-y-2 opacity-30 px-6">
                 <MessageSquare className="w-10 h-10 mb-2" />
                 <p className="text-xs">Ask me for scene ideas, lighting tips, or how to get the best product shots!</p>
              </div>
            )}
            {chatMessages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-4 py-2.5 rounded-2xl text-sm ${msg.role === 'user' ? 'bg-indigo-600' : 'bg-white/5 border border-white/10'}`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isChatting && (
              <div className="flex justify-start">
                <div className="bg-white/5 border border-white/10 px-4 py-2.5 rounded-2xl">
                   <div className="flex gap-1">
                      <div className="w-1 h-1 bg-white/40 rounded-full animate-bounce" style={{animationDelay: '0ms'}} />
                      <div className="w-1 h-1 bg-white/40 rounded-full animate-bounce" style={{animationDelay: '150ms'}} />
                      <div className="w-1 h-1 bg-white/40 rounded-full animate-bounce" style={{animationDelay: '300ms'}} />
                   </div>
                </div>
              </div>
            )}
            <div ref={chatEndRef} />
          </div>

          <div className="p-4 bg-white/5 border-t border-white/10">
            <div className="relative">
              <input 
                type="text" 
                placeholder="Ask assistant..."
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                className="w-full bg-black/40 border border-white/10 rounded-full px-5 py-3 pr-12 text-sm focus:outline-none focus:ring-1 focus:ring-indigo-500"
              />
              <button 
                onClick={handleSendMessage}
                disabled={isChatting || !chatInput.trim()}
                className="absolute right-2 top-2 p-1.5 bg-indigo-500 rounded-full hover:bg-indigo-400 transition-colors disabled:opacity-50"
              >
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

{
  "name": "Lumina AI 视觉工作室 - 高端产品摄影",
