}

import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { SceneStyle, ImageSize } from "./types";

const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const replaceBackground = async (
  base64Image: string,
  style: SceneStyle,
  customPrompt: string,
  isPro: boolean = false,
  size: ImageSize = ImageSize.SIZE_1K
): Promise<string> => {
  const ai = getAIClient();
  const modelName = isPro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const stylePrompts: Record<string, string> = {
    ['现代奢华风']: "Place the product in a high-end luxury penthouse with floor-to-ceiling windows, marble floors, and sophisticated lighting.",
    ['北欧极简风']: "Place the product in a bright, airy Scandinavian room with light wood furniture, soft textiles, and clean lines.",
    ['工业水泥风']: "Place the product in a loft with exposed brick walls, concrete floors, and large industrial windows with sunset light.",
    ['经典优雅风']: "Place the product in a grand heritage mansion room with ornate moldings, mahogany furniture, and velvet accents.",
    ['田园温馨风']: "Place the product in a cozy cabin or stone house with natural textures, warm golden hour lighting, and organic surroundings.",
    ['未来科技风']: "Place the product in a sleek, neo-futuristic laboratory or modern office with neon accents and high-tech surfaces."
  };

  const finalPrompt = `
    TASK: BACKGROUND REPLACEMENT.
    STRICT RULE: KEEP THE MAIN PRODUCT EXACTLY AS IT IS. Do not change its shape, color, texture, or gloss.
    INSTRUCTION: ${stylePrompts[style] || style} ${customPrompt ? `Additional user request: ${customPrompt}` : ''}
    LIGHTING: Ensure the product's lighting and shadows perfectly match the new environment. 
    REALISM: Add realistic reflections of the new background on the product surface if it's shiny.
    OUTPUT: A professional, high-resolution lifestyle photograph.
  `;

  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image.split(',')[1],
    },
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [imagePart, { text: finalPrompt }] },
    config: isPro ? {
      imageConfig: {
        aspectRatio: "1:1",
        imageSize: size
      }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gemini 未返回图像数据");
};

export const startChat = async (history: {role: 'user' | 'model', parts: {text: string}[]}[]) => {
  const ai = getAIClient();
