import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { SceneStyle, ImageSize } from "./types";

const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const replaceBackground = async (
  base64Image: string,
  style: SceneStyle,
  customPrompt: string,
  isPro: boolean = false,
  size: ImageSize = ImageSize.SIZE_1K,
  addReference: boolean = false
): Promise<string> => {
  const ai = getAIClient();
  const modelName = isPro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  const stylePrompts: Record<string, string> = {
    [SceneStyle.BLACK_GOLD_SLATE]: "Place the product on a premium black slate with elegant gold veins. Cinematic low-key lighting, sharp reflections on the surface, dark luxury studio background.",
    [SceneStyle.ZEN_WOOD]: "Place the product on a weathered natural wooden table. Soft morning sunlight filtering through bamboo leaves creating dappled shadows. Zen aesthetic with a blurred tea room background.",
    [SceneStyle.C4D_GEOMETRIC]: "Professional e-commerce 3D render style. Product stands on a clean geometric podium. Soft pastel Morandi color palette, minimal abstract shapes, studio softbox lighting.",
    [SceneStyle.WINDOW_LIGHT]: "Bright indoor setting. Product sits near a large window with morning sun. Realistic venetian blind shadows casting across the scene, airy and fresh atmosphere.",
    [SceneStyle.WARM_BOKEH]: "Cozy evening atmosphere. Warm amber lighting with soft bokeh balls in the background. Indoor home environment, peaceful and relaxing mood.",
    [SceneStyle.CHAOZHOU_STREET]: "Traditional Chaozhou Paifang Street background. Product placed on a clean stone pedestal. Lingnan architecture, historical arches, warm cultural lighting.",
    [SceneStyle.HAN_RIVER]: "Scenic Han River in spring. Product placed on a reflective outdoor terrace. Blooming kapok flowers along the river, soft sunlight on the water surface.",
    [SceneStyle.MODERN_LUXURY]: "Luxury penthouse interior, marble surfaces, floor-to-ceiling windows, sophisticated city night view.",
    [SceneStyle.NORDIC_MINIMALIST]: "Scandinavian minimalist room, light oak furniture, white walls, soft textiles, clean daylight."
  };

  // 比例校正补丁：如果开启，强制加入微小的参照物
  const referencePrompt = addReference 
    ? "SCALE FIX: Include a small, blurry tea cup or an open book in the distance as a size reference to ensure the main product maintains a realistic proportion."
    : "";

  const finalPrompt = `
    TASK: PROFESSIONAL PRODUCT BACKGROUND REPLACEMENT.
    STRICT RULE: MAINTAIN PRODUCT INTEGRITY. Do not modify the product's shape, color, or texture.
    SCENE: ${stylePrompts[style] || style}
    ${referencePrompt}
    USER REQUEST: ${customPrompt}
    LIGHTING & PERSPECTIVE: Ensure seamless integration. Shadows and reflections must match the new environment perfectly.
    QUALITY: High-resolution, professional commercial photography, 8k, sharp focus on the main product.
  `;

  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image.split(',')[1],
    },
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [imagePart, { text: finalPrompt }] },
    config: isPro ? {
      imageConfig: {
        aspectRatio: "1:1",
        imageSize: size
      }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gemini 未返回图像数据");
};

