import React, { useState, useCallback, useRef } from 'react';
import { 
  Camera, 
  Upload, 
  Sparkles, 
  Download, 
  MessageSquare, 
  X, 
  ChevronRight,
  Settings,
  RefreshCw,
  Zap,
  Check,
  LayoutGrid,
  Maximize2
} from 'lucide-react';
import { SceneStyle, ImageSize, GenerationConfig, ChatMessage, GenerationResult } from './types';
import { replaceBackground, startChat } from './geminiService';
import { GoogleGenAI } from '@google/genai';

const App: React.FC = () => {
  const [selectedFile, setSelectedFile] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [config, setConfig] = useState<GenerationConfig>({
    style: SceneStyle.BLACK_GOLD_SLATE,
    customPrompt: '',
    isPro: false,
    size: ImageSize.SIZE_1K,
    addReference: true // 默认开启比例参考
  });

  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatting, setIsChatting] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setSelectedFile(event.target?.result as string);
        setResult(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!selectedFile) return;
    setIsProcessing(true);
    try {
      if (config.isPro) {
        // @ts-ignore
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) {
          // @ts-ignore
          await window.aistudio.openSelectKey();
        }
      }

      const resultUrl = await replaceBackground(
        selectedFile,
        config.style,
        config.customPrompt,
        config.isPro,
        config.size,
        config.addReference
      );

      setResult({
        originalUrl: selectedFile,
        resultUrl,
        id: Date.now().toString()
      });
    } catch (error: any) {
      console.error("生成失败:", error);
      if (error.message?.includes("Requested entity was not found")) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      } else {
        alert("图像生成失败，请重试。");
      }
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: chatInput };
    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatting(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const chat = ai.chats.create({
        model: 'gemini-3-pro-preview',
        config: { systemInstruction: "你是一位 Lumina AI 视觉工作室的专业摄影助手。请使用中文回答。" }
      });
      const response = await chat.sendMessage({ message: chatInput });
      const modelMsg: ChatMessage = { role: 'model', text: response.text || '抱歉，我无法处理该请求。' };
      setChatMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      console.error("对话错误:", error);
    } finally {
      setIsChatting(false);
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const downloadImage = () => {
    if (!result) return;
    const link = document.createElement('a');
    link.href = result.resultUrl;
    link.download = `lumina-ai-${result.id}.png`;
    link.click();
  };

  const styleCategories = [
    { name: '商业底座', styles: [SceneStyle.BLACK_GOLD_SLATE, SceneStyle.ZEN_WOOD, SceneStyle.C4D_GEOMETRIC] },
    { name: '光影氛围', styles: [SceneStyle.WINDOW_LIGHT, SceneStyle.WARM_BOKEH, SceneStyle.MODERN_LUXURY] },
    { name: '人文地理', styles: [SceneStyle.CHAOZHOU_STREET, SceneStyle.HAN_RIVER, SceneStyle.NORDIC_MINIMALIST] }
  ];

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#0a0a0a] text-white">
      {/* 侧边栏 */}
      <aside className="w-full md:w-[400px] border-r border-white/10 bg-[#0f0f0f] p-6 flex flex-col gap-6 overflow-y-auto">
        <header className="flex items-center gap-3 mb-2">
          <div className="p-2 bg-indigo-600 rounded-lg">
            <Sparkles className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="font-bold text-lg leading-tight">崇正科技 AI</h1>
            <p className="text-[10px] text-white/40 uppercase tracking-widest font-bold">Lumina Studio v2.0</p>
          </div>
        </header>

        {/* 1. 上传 */}
        <div className="space-y-3">
          <label className="text-xs font-bold text-white/40 uppercase tracking-wider block">1. 上传产品原图</label>
          <div className={`relative group cursor-pointer border-2 border-dashed ${selectedFile ? 'border-indigo-500' : 'border-white/10'} rounded-2xl transition-all hover:bg-white/5 aspect-square overflow-hidden flex flex-col items-center justify-center`}>
            {selectedFile ? (
              <img src={selectedFile} alt="Uploaded" className="w-full h-full object-contain p-4" />
            ) : (
              <div className="text-center p-4">
                <Upload className="w-10 h-10 text-white/20 mx-auto mb-3" />
                <p className="text-xs text-white/40 font-medium">点击或拖拽上传</p>
              </div>
            )}
            <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" />
          </div>
        </div>

        {/* 2. 预设场景 */}
        <div className="space-y-4">
          <label className="text-xs font-bold text-white/40 uppercase tracking-wider block">2. 选择场景风格</label>
          {styleCategories.map(cat => (
            <div key={cat.name} className="space-y-2">
              <span className="text-[10px] text-white/30 font-bold ml-1">{cat.name}</span>
              <div className="grid grid-cols-3 gap-2">
                {cat.styles.map(s => (
                  <button
                    key={s}
                    onClick={() => setConfig({...config, style: s})}
                    className={`py-2 text-[11px] rounded-lg border transition-all truncate px-1 ${config.style === s ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg shadow-indigo-600/20' : 'border-white/5 text-white/60 hover:border-white/20 hover:bg-white/5'}`}
                  >
                    {s}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>

        {/* 3. 高级控制 */}
        <div className="space-y-4 pt-4 border-t border-white/5">
          <div className="flex items-center justify-between p-3 bg-white/5 rounded-xl border border-white/5">
            <div className="flex items-center gap-2">
              <Maximize2 className={`w-4 h-4 ${config.addReference ? 'text-green-400' : 'text-white/20'}`} />
              <div>
                <span className="text-xs font-bold block">比例校正补丁</span>
                <span className="text-[10px] text-white/30">自动添加参照物防止“巨大化”</span>
              </div>
            </div>
            <button 
              onClick={() => setConfig({...config, addReference: !config.addReference})}
              className={`w-10 h-5 rounded-full relative transition-colors ${config.addReference ? 'bg-green-500' : 'bg-white/10'}`}
            >
              <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${config.addReference ? 'left-6' : 'left-1'}`} />
            </button>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-white/40 uppercase tracking-wider block">自定义要求 (可选)</label>
            <textarea 
              placeholder="例如：背景稍微暗一点..."
              value={config.customPrompt}
              onChange={(e) => setConfig({...config, customPrompt: e.target.value})}
              className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-xs h-20 focus:outline-none focus:ring-1 focus:ring-indigo-500 resize-none"
            />
          </div>
        </div>

        {/* 生成按钮 */}
        <button 
          onClick={handleGenerate}
          disabled={!selectedFile || isProcessing}
          className={`w-full py-4 mt-auto rounded-2xl font-bold flex items-center justify-center gap-3 transition-all ${isProcessing ? 'bg-white/5 text-white/20 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-500 active:scale-[0.98] shadow-2xl shadow-indigo-600/30'}`}
        >
          {isProcessing ? (
            <><RefreshCw className="w-5 h-5 animate-spin" /> 构思画作中...</>
          ) : (
            <><Sparkles className="w-5 h-5" /> 开始商业大片生成</>
          )}
        </button>
      </aside>

      {/* 主画布 */}
      <main className="flex-1 p-6 md:p-12 flex flex-col items-center justify-center bg-[#0a0a0a]">
        <div className="max-w-5xl w-full h-full flex flex-col items-center justify-center gap-8">
          {!result && !isProcessing && (
            <div className="text-center space-y-4 opacity-20">
               <LayoutGrid className="w-24 h-24 mx-auto text-white" />
               <h2 className="text-xl font-light tracking-widest uppercase">等待创意点燃</h2>
            </div>
          )}

          {isProcessing && (
            <div className="text-center animate-pulse space-y-6">
               <div className="w-64 h-64 border-2 border-indigo-500/20 rounded-full flex items-center justify-center">
                 <div className="w-48 h-48 border-2 border-indigo-500/40 rounded-full flex items-center justify-center animate-[spin_3s_linear_infinite]">
                    <Sparkles className="w-12 h-12 text-indigo-500" />
                 </div>
               </div>
               <p className="text-sm tracking-[0.2em] text-white/60">正在进行光影重构与透视校正</p>
            </div>
          )}

          {result && !isProcessing && (
            <div className="w-full group animate-in zoom-in-95 duration-700">
               <div className="relative rounded-3xl overflow-hidden shadow-[0_50px_100px_-20px_rgba(0,0,0,0.8)] border border-white/5">
                  <img src={result.resultUrl} alt="Result" className="w-full h-auto object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                  <div className="absolute bottom-8 right-8 flex gap-4 opacity-0 group-hover:opacity-100 transition-all duration-500 translate-y-4 group-hover:translate-y-0">
                     <button 
                       onClick={downloadImage}
                       className="flex items-center gap-2 px-6 py-3 bg-white text-black rounded-full font-bold hover:scale-105 transition-transform"
                     >
                       <Download className="w-5 h-5" /> 下载 8K 原图
                     </button>
                     <button 
                       onClick={() => setResult(null)}
                       className="p-3 bg-white/10 backdrop-blur-md border border-white/20 rounded-full hover:bg-white/20 transition-colors"
                     >
                       <RefreshCw className="w-6 h-6" />
                     </button>
                  </div>
               </div>
            </div>
          )}
        </div>

        {/* 水印 */}
        <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-3 opacity-20 select-none">
           <div className="h-px w-12 bg-white" />
           <span className="text-[10px] font-bold tracking-[0.5em] uppercase">Chongzheng Vision Studio</span>
           <div className="h-px w-12 bg-white" />
        </div>
      </main>

      {/* 助手 */}
      <button 
        onClick={() => setShowChat(!showChat)}
        className={`fixed bottom-8 right-8 p-4 rounded-2xl shadow-2xl z-50 transition-all ${showChat ? 'bg-red-500' : 'bg-indigo-600 hover:scale-110'}`}
      >
        {showChat ? <X /> : <MessageSquare />}
      </button>

      {showChat && (
        <div className="fixed bottom-24 right-8 w-80 md:w-96 h-[500px] bg-[#121212] border border-white/10 rounded-3xl shadow-2xl flex flex-col z-50 overflow-hidden animate-in slide-in-from-bottom-5">
           <header className="p-4 border-b border-white/5 bg-white/5 flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
              <span className="text-xs font-bold">Lumina 专家系统在线</span>
           </header>
           <div className="flex-1 overflow-y-auto p-4 space-y-4">
              {chatMessages.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                   <div className={`max-w-[85%] px-4 py-2 rounded-2xl text-xs leading-relaxed ${msg.role === 'user' ? 'bg-indigo-600' : 'bg-white/5 border border-white/10'}`}>
                      {msg.text}
                   </div>
                </div>
              ))}
              {isChatting && <div className="text-[10px] text-white/20 ml-2">正在思考...</div>}
              <div ref={chatEndRef} />
