                   onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                   placeholder="咨询摄影建议..." 
                   className="flex-1 bg-black border border-white/10 rounded-xl px-4 py-2 text-xs focus:outline-none focus:ring-1 focus:ring-indigo-500"
                 />
                 <button onClick={handleSendMessage} className="p-2 bg-indigo-600 rounded-xl"><ChevronRight /></button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

