  originalUrl: string;
  resultUrl: string;
  id: string;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { SceneStyle, EnvironmentType, ImageSize } from "./types";

const getAIClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const replaceBackground = async (
  base64Image: string,
  environment: EnvironmentType,
  style: SceneStyle,
  customPrompt: string,
  isPro: boolean = false,
  size: ImageSize = ImageSize.SIZE_1K,
  addReference: boolean = false
): Promise<string> => {
  const ai = getAIClient();
  const modelName = isPro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

  // 空间背景逻辑
  const envPrompts: Record<string, string> = {
    [EnvironmentType.BEDROOM]: "in a cozy, high-end bedroom setting, perhaps on a bedside table or a soft textured rug near a bed.",
    [EnvironmentType.DINING_ROOM]: "on a sophisticated dining table, surrounded by elegant dinnerware and a warm home atmosphere.",
    [EnvironmentType.OUTDOOR_PICNIC]: "in a lush green outdoor park or garden, placed on a picnic cloth or a rustic wooden bench.",
    [EnvironmentType.BATHROOM]: "in a clean, modern luxury bathroom, placed on a marble vanity or near a freestanding bathtub.",
    [EnvironmentType.LIVING_ROOM]: "in a designer living room, on a coffee table or a minimalist side cabinet.",
    [EnvironmentType.OFFICE]: "in a high-tech modern office environment, on a polished desk or a meeting room table.",
    [EnvironmentType.STUDIO]: "in a professional clean commercial photography studio with high-end backdrops.",
    [EnvironmentType.CAFE]: "in a trendy urban boutique cafe, on a small round table with soft ambient noise."
  };

  // 艺术风格逻辑
  const stylePrompts: Record<string, string> = {
    [SceneStyle.MODERN_LUXURY]: "Rendered with high-end luxury aesthetics, marble textures, and expensive materials. Crisp and clean look.",
    [SceneStyle.ZEN_MINIMALIST]: "Soft, peaceful Zen atmosphere. Use natural elements like wood, stone, and bamboo. Muted earthy tones.",
    [SceneStyle.C4D_GEOMETRIC]: "Professional 3D C4D render style. Use clean geometric shapes, soft pastel colors, and perfect studio lighting.",
    [SceneStyle.WINDOW_LIGHT]: "Bathed in soft, natural morning sunlight through a window. Realistic soft shadows and airy feel.",
    [SceneStyle.WARM_BOKEH]: "Deep cinematic depth of field with warm golden hour bokeh in the background. Cozy and inviting.",
    [SceneStyle.BLACK_GOLD]: "Moody dark aesthetic with premium black slate and elegant gold accents. Sharp, reflective lighting.",
    [SceneStyle.CHAOZHOU_RETRO]: "Nostalgic atmosphere featuring traditional Southern Chinese architecture elements and cultural textures."
  };

  // 动态参照物逻辑
  const referenceMap: Record<string, string> = {
    [EnvironmentType.BEDROOM]: "a blurry small bedside lamp or a book",
    [EnvironmentType.DINING_ROOM]: "a blurry wine glass or a small plate",
    [EnvironmentType.OUTDOOR_PICNIC]: "a few blurry blades of grass or a wild flower",
    [EnvironmentType.BATHROOM]: "a small blurry bottle of essential oil or a towel edge",
    [EnvironmentType.LIVING_ROOM]: "a blurry remote control or a small coaster",
    [EnvironmentType.OFFICE]: "a blurry pen or a corner of a laptop",
    [EnvironmentType.STUDIO]: "a blurred photography color checker card",
    [EnvironmentType.CAFE]: "a small blurry espresso cup"
  };

  const refObject = referenceMap[environment] || "a common lifestyle object";
  const referencePrompt = addReference 
    ? `SCALE FIX: Include ${refObject} in the background or at the edge of the frame. It must be out of focus (blurry) to provide a size reference.`
    : "";

  const finalPrompt = `
    TASK: PROFESSIONAL PRODUCT RE-STYLING. 
    THE PRODUCT: The main object provided in the image must be preserved exactly in terms of shape and color.
    LOCATION: The product is placed ${envPrompts[environment]}.
    VISUAL STYLE: ${stylePrompts[style]}.
    ${referencePrompt}
    ADDITIONAL USER DETAILS: ${customPrompt}
    INTEGRATION: Perfect perspective and high-quality shadow mapping. 8k resolution, commercial photography quality.
  `;

  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image.split(',')[1],
    },
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [imagePart, { text: finalPrompt }] },
    config: isPro ? {
      imageConfig: { aspectRatio: "1:1", imageSize: size }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gemini 未返回图像数据");
};

