  };

  // 动态参照物逻辑
  const referenceMap: Record<string, string> = {
    [EnvironmentType.BEDROOM]: "a blurry small bedside lamp or a book",
    [EnvironmentType.DINING_ROOM]: "a blurry wine glass or a small plate",
    [EnvironmentType.OUTDOOR_PICNIC]: "a few blurry blades of grass or a wild flower",
    [EnvironmentType.BATHROOM]: "a small blurry bottle of essential oil or a towel edge",
    [EnvironmentType.LIVING_ROOM]: "a blurry remote control or a small coaster",
    [EnvironmentType.OFFICE]: "a blurry pen or a corner of a laptop",
    [EnvironmentType.STUDIO]: "a blurred photography color checker card",
    [EnvironmentType.CAFE]: "a small blurry espresso cup"
  };

  const refObject = referenceMap[environment] || "a common lifestyle object";
  const referencePrompt = addReference 
    ? `SCALE FIX: Include ${refObject} in the background or at the edge of the frame. It must be out of focus (blurry) to provide a size reference.`
    : "";

  const cleaningPrompt = cleanProduct 
    ? "PRODUCT RETOUCHING: Please digitally clean the product. Remove any visible dust, fingerprints, smudges, or minor surface imperfections. Ensure the product looks brand new and pristine while keeping its authentic texture."
    : "";

  const finalPrompt = `
    TASK: PROFESSIONAL PRODUCT RE-STYLING. 
    THE PRODUCT: The main object provided in the image must be preserved exactly in terms of shape and color.
    ${cleaningPrompt}
    LOCATION: The product is placed ${envPrompts[environment]}.
    VISUAL STYLE: ${stylePrompts[style]}.
    ${referencePrompt}
    ADDITIONAL USER DETAILS: ${customPrompt}
    INTEGRATION: Perfect perspective and high-quality shadow mapping. 8k resolution, commercial photography quality.
  `;

  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Image.split(',')[1],
    },
  };

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [imagePart, { text: finalPrompt }] },
    config: isPro ? {
      imageConfig: { aspectRatio: "1:1", imageSize: size }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gemini 未返回图像数据");
};

export const startChat = async (history: any[]) => {
  const ai = getAIClient();
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: "你是一位 Lumina AI 视觉工作室的专业摄影助手。你特别擅长处理产品的比例感、光影融合和电商背景设计。请使用中文回答。"
    }
  });
};

import React, { useState, useRef } from 'react';
import { 
  Upload, 
  Sparkles, 
  Download, 
  MessageSquare, 
  X, 
  ChevronRight,
  RefreshCw,
  LayoutGrid,
  Maximize2,
  Home,
  Palette,
  Layers,
  Wand2
} from 'lucide-react';
import { SceneStyle, EnvironmentType, ImageSize, GenerationConfig, ChatMessage, GenerationResult } from './types';
import { replaceBackground } from './geminiService';
import { GoogleGenAI } from '@google/genai';

const App: React.FC = () => {
  const [selectedFile, setSelectedFile] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [config, setConfig] = useState<GenerationConfig>({
    environment: EnvironmentType.DINING_ROOM,
    style: SceneStyle.WINDOW_LIGHT,
    customPrompt: '',
    isPro: false,
    size: ImageSize.SIZE_1K,
    addReference: true,
    cleanProduct: false
  });

  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatting, setIsChatting] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setSelectedFile(event.target?.result as string);
        setResult(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!selectedFile) return;
    setIsProcessing(true);
    try {
      const resultUrl = await replaceBackground(
        selectedFile,
        config.environment,
        config.style,
        config.customPrompt,
        config.isPro,
        config.size,
        config.addReference,
        config.cleanProduct
      );

      setResult({
        originalUrl: selectedFile,
        resultUrl,
        id: Date.now().toString()
      });
    } catch (error: any) {
      console.error("生成失败:", error);
      alert("生成失败，请检查网络或配置。");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: chatInput };
    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatting(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const chat = ai.chats.create({
        model: 'gemini-3-pro-preview',
        config: { systemInstruction: "你是一位 Lumina AI 视觉工作室的专业摄影助手。请使用中文回答。" }
      });
      const response = await chat.sendMessage({ message: chatInput });
      const modelMsg: ChatMessage = { role: 'model', text: response.text || '抱歉，我无法处理该请求。' };
      setChatMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      console.error("对话错误:", error);
    } finally {
      setIsChatting(false);
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#080808] text-white selection:bg-indigo-500/30">
      {/* 侧边栏 */}
      <aside className="w-full md:w-[380px] border-r border-white/5 bg-[#0c0c0c] p-8 flex flex-col gap-8 overflow-y-auto">
        <header className="flex items-center gap-4">
          <div className="p-2.5 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl shadow-lg shadow-indigo-500/20">
            <Sparkles className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="font-bold text-xl tracking-tight">崇正视觉 Pro</h1>
            <p className="text-[10px] text-white/30 uppercase tracking-[0.2em] font-black">Lumina Studio v2.5</p>
          </div>
        </header>

        {/* 1. 上传 */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1">
             <Upload className="w-3 h-3 text-indigo-400" />
             <label className="text-[10px] font-black text-white/40 uppercase tracking-widest">第一步：上传原图</label>
          </div>
          <div className={`relative group cursor-pointer border-2 border-dashed ${selectedFile ? 'border-indigo-500/50 bg-indigo-500/5' : 'border-white/5 bg-white/[0.02]'} rounded-3xl transition-all hover:border-indigo-500/30 hover:bg-white/[0.04] aspect-square overflow-hidden flex flex-col items-center justify-center`}>
            {selectedFile ? (
              <img src={selectedFile} alt="Uploaded" className="w-full h-full object-contain p-6" />
            ) : (
              <div className="text-center p-6 space-y-3">
                <div className="w-12 h-12 bg-white/5 rounded-full flex items-center justify-center mx-auto">
                   <Upload className="w-6 h-6 text-white/40" />
                </div>
                <p className="text-[11px] text-white/40 font-medium">支持 JPG, PNG, WebP</p>
              </div>
            )}
            <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" />
          </div>
        </section>

        {/* 2. 空间场景 */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1">
             <Home className="w-3 h-3 text-indigo-400" />
             <label className="text-[10px] font-black text-white/40 uppercase tracking-widest">第二步：空间场景</label>
          </div>
          <select 
            value={config.environment}
            onChange={(e) => setConfig({...config, environment: e.target.value as EnvironmentType})}
            className="w-full bg-white/[0.05] border border-white/10 rounded-2xl px-4 py-3.5 text-sm appearance-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all"
          >
            {Object.values(EnvironmentType).map(env => (
              <option key={env} value={env} className="bg-[#1a1a1a]">{env}</option>
            ))}
          </select>
        </section>

        {/* 3. 视觉风格 */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1">
             <Palette className="w-3 h-3 text-indigo-400" />
             <label className="text-[10px] font-black text-white/40 uppercase tracking-widest">第三步：艺术风格</label>
          </div>
          <select 
            value={config.style}
            onChange={(e) => setConfig({...config, style: e.target.value as SceneStyle})}
            className="w-full bg-white/[0.05] border border-white/10 rounded-2xl px-4 py-3.5 text-sm appearance-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all"
          >
            {Object.values(SceneStyle).map(style => (
              <option key={style} value={style} className="bg-[#1a1a1a]">{style}</option>
            ))}
          </select>
        </section>

        {/* 4. 高级补丁 */}
        <section className="space-y-4 bg-white/[0.02] p-5 rounded-3xl border border-white/5">
           <div className="flex flex-col gap-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className={`p-1.5 rounded-lg ${config.addReference ? 'bg-indigo-500/20 text-indigo-400' : 'bg-white/5 text-white/20'}`}>
                      <Maximize2 className="w-4 h-4" />
                  </div>
                  <span className="text-xs font-bold">智能比例修正</span>
                </div>
                <button 
                  onClick={() => setConfig({...config, addReference: !config.addReference})}
                  className={`w-11 h-6 rounded-full relative transition-all duration-300 ${config.addReference ? 'bg-indigo-500 shadow-[0_0_15px_rgba(99,102,241,0.4)]' : 'bg-white/10'}`}
                >
                  <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all duration-300 ${config.addReference ? 'left-6' : 'left-1'}`} />
                </button>
              </div>

              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className={`p-1.5 rounded-lg ${config.cleanProduct ? 'bg-indigo-500/20 text-indigo-400' : 'bg-white/5 text-white/20'}`}>
                      <Wand2 className="w-4 h-4" />
                  </div>
                  <span className="text-xs font-bold">清洁物品 (去污)</span>
                </div>
                <button 
                  onClick={() => setConfig({...config, cleanProduct: !config.cleanProduct})}
                  className={`w-11 h-6 rounded-full relative transition-all duration-300 ${config.cleanProduct ? 'bg-indigo-500 shadow-[0_0_15px_rgba(99,102,241,0.4)]' : 'bg-white/10'}`}
                >
                  <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all duration-300 ${config.cleanProduct ? 'left-6' : 'left-1'}`} />
                </button>
              </div>
           </div>

           <div className="space-y-2 pt-2 border-t border-white/5">
             <div className="flex items-center gap-2 opacity-40">
                <Layers className="w-3 h-3" />
                <span className="text-[10px] font-bold uppercase tracking-wider">自定义细节</span>
             </div>
             <textarea 
               placeholder="例如：背景虚化深一点，桌面上放几朵干花..."
               value={config.customPrompt}
               onChange={(e) => setConfig({...config, customPrompt: e.target.value})}
               className="w-full bg-transparent text-xs py-2 h-16 focus:outline-none placeholder:text-white/20 resize-none"
             />
           </div>
        </section>

        <button 
          onClick={handleGenerate}
          disabled={!selectedFile || isProcessing}
          className={`w-full py-5 rounded-3xl font-bold text-sm tracking-wide flex items-center justify-center gap-3 transition-all ${isProcessing ? 'bg-white/5 text-white/20 cursor-not-allowed' : 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:scale-[1.02] active:scale-[0.98] shadow-xl shadow-indigo-600/20'}`}
        >
          {isProcessing ? <RefreshCw className="w-5 h-5 animate-spin" /> : <><Sparkles className="w-5 h-5" /> 立即生成商业大片</>}
        </button>
      </aside>

      {/* 画布 */}
      <main className="flex-1 relative flex items-center justify-center p-8 md:p-16">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-indigo-500/[0.03] via-transparent to-transparent pointer-events-none" />

        <div className="w-full max-w-4xl aspect-square flex items-center justify-center relative">
          {!result && !isProcessing && (
            <div className="text-center group">
               <div className="w-32 h-32 bg-white/[0.02] border border-white/5 rounded-[40px] flex items-center justify-center mx-auto mb-8 group-hover:scale-110 transition-transform duration-700">
                  <LayoutGrid className="w-12 h-12 text-white/10" />
               </div>
               <p className="text-sm font-light text-white/20 tracking-[0.3em] uppercase">等待灵感注入</p>
            </div>
          )}

          {isProcessing && (
            <div className="flex flex-col items-center gap-8">
               <div className="relative">
                  <div className="w-24 h-24 border-2 border-indigo-500/20 rounded-full animate-ping" />
                  <Sparkles className="w-8 h-8 text-indigo-500 absolute inset-0 m-auto animate-pulse" />
               </div>
               <div className="space-y-2 text-center">
                  <p className="text-sm font-medium text-white/60">正在重构光影与深度...</p>
                  <p className="text-[10px] text-white/20 uppercase tracking-widest">Retouching & Composing</p>
               </div>
            </div>
          )}

          {result && !isProcessing && (
            <div className="w-full h-full relative group animate-in zoom-in-95 duration-700">
               <div className="w-full h-full rounded-[40px] overflow-hidden shadow-2xl border border-white/10">
                  <img src={result.resultUrl} alt="Result" className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all duration-500 flex flex-col justify-end p-12">
                     <div className="flex items-center justify-between gap-4 translate-y-4 group-hover:translate-y-0 transition-transform duration-500">
                        <div>
                           <h3 className="font-bold text-lg">{config.environment} · {config.style}</h3>
                           <p className="text-xs text-white/40">AI Generated Masterpiece</p>
                        </div>
                        <div className="flex gap-3">
                           <button 
                             onClick={() => setResult(null)}
                             className="p-4 bg-white/10 hover:bg-white/20 rounded-2xl backdrop-blur-xl transition-colors"
                           >
                             <RefreshCw className="w-6 h-6" />
                           </button>
                           <button 
                             onClick={() => {
                               const link = document.createElement('a');
                               link.href = result.resultUrl;
                               link.download = "lumina-pro-export.png";
                               link.click();
                             }}
                             className="flex items-center gap-3 px-8 py-4 bg-white text-black rounded-2xl font-bold hover:scale-105 transition-all"
                           >
                             <Download className="w-5 h-5" /> 导出 8K 样片
                           </button>
                        </div>
                     </div>
                  </div>
               </div>
            </div>
          )}
        </div>

        {/* 聊天入口 */}
        <button 
          onClick={() => setShowChat(!showChat)}
          className={`fixed bottom-10 right-10 p-5 rounded-3xl shadow-2xl z-50 transition-all ${showChat ? 'bg-red-500 scale-90' : 'bg-indigo-600 hover:scale-110 hover:rotate-6'}`}
        >
          {showChat ? <X /> : <MessageSquare />}
        </button>

        {showChat && (
          <div className="fixed bottom-32 right-10 w-80 md:w-[400px] h-[550px] bg-[#121212] border border-white/10 rounded-[40px] shadow-2xl flex flex-col z-50 overflow-hidden animate-in slide-in-from-bottom-10">
             <header className="p-6 border-b border-white/5 bg-white/[0.02] flex items-center justify-between">
                <div className="flex items-center gap-3">
                   <div className="w-2.5 h-2.5 rounded-full bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]" />
                   <span className="text-xs font-bold tracking-widest uppercase opacity-60">专家顾问</span>
                </div>
                <button onClick={() => setShowChat(false)} className="opacity-20 hover:opacity-100"><X className="w-4 h-4" /></button>
             </header>
             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                {chatMessages.length === 0 && (
                   <div className="h-full flex flex-col items-center justify-center opacity-20 text-center space-y-4">
                      <MessageSquare className="w-12 h-12" />
                      <p className="text-[11px] uppercase tracking-widest font-bold">询问拍摄建议或后期修改</p>
                   </div>
                )}
                {chatMessages.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                     <div className={`max-w-[85%] px-5 py-3 rounded-2xl text-[13px] leading-relaxed ${msg.role === 'user' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white/5 border border-white/10 text-white/80'}`}>
                        {msg.text}
                     </div>
                  </div>
                ))}
                {isChatting && <div className="text-[10px] text-white/20 animate-pulse ml-2 font-bold uppercase tracking-widest">AI Agent Thinking...</div>}
                <div ref={chatEndRef} />
             </div>
             <div className="p-6 bg-white/[0.02] border-t border-white/5">
                <div className="flex gap-3">
                   <input 
                     type="text" 
                     value={chatInput} 
                     onChange={e => setChatInput(e.target.value)}
                     onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                     placeholder="咨询摄影建议..." 
                     className="flex-1 bg-black/40 border border-white/10 rounded-2xl px-5 py-3 text-sm focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-all"
                   />
                   <button onClick={handleSendMessage} className="w-12 h-12 flex items-center justify-center bg-indigo-600 rounded-2xl hover:bg-indigo-500 transition-colors shadow-lg shadow-indigo-600/20"><ChevronRight /></button>
                </div>
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;
